-- Program business codes: generated by PostgreSQL instead of typed by hand.
-- Canonical format PRG-0001, PRG-0002, ... -- globally unique (programs.code
-- already carries a global UNIQUE constraint from 000001), monotonic, never
-- derived from name/species/campaign, never reused (sequences only move
-- forward, and the UNIQUE constraint keeps an archived program's code taken).
-- next_breeding_business_code() (000014) already derives its program prefix
-- generically from programs.code via UPPER(REGEXP_REPLACE(code, ...)), so
-- "PRG-0001" alone yields the expected "PRG0001-P-0001" etc. prefix with no
-- change required there.
CREATE SEQUENCE public.program_code_seq;
REVOKE ALL ON SEQUENCE public.program_code_seq FROM PUBLIC, anon, authenticated;

CREATE FUNCTION public.next_program_business_code()
RETURNS TEXT
LANGUAGE plpgsql
VOLATILE
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
  candidate TEXT;
BEGIN
  LOOP
    candidate := 'PRG-' || LPAD(NEXTVAL('public.program_code_seq')::TEXT, 4, '0');
    EXIT WHEN NOT EXISTS (SELECT 1 FROM public.programs WHERE code = candidate);
  END LOOP;
  RETURN candidate;
END;
$$;

REVOKE ALL ON FUNCTION public.next_program_business_code()
  FROM PUBLIC, anon, authenticated;

-- Assigns the code only when the client did not already supply one, so the
-- handful of pre-existing, manually-entered program codes stay untouched.
CREATE FUNCTION public.assign_program_business_code()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
BEGIN
  IF NULLIF(BTRIM(NEW.code), '') IS NULL THEN
    NEW.code := public.next_program_business_code();
  END IF;
  RETURN NEW;
END;
$$;

REVOKE ALL ON FUNCTION public.assign_program_business_code()
  FROM PUBLIC, anon, authenticated;

CREATE TRIGGER assign_program_business_code_trigger
  BEFORE INSERT ON public.programs
  FOR EACH ROW EXECUTE FUNCTION public.assign_program_business_code();

-- Reuses the same generic immutability guard already protecting parent/cross/
-- family/seed_lot/phenotype business codes (000014): once assigned, a
-- program's code cannot be rewritten.
CREATE TRIGGER guard_program_business_code_trigger
  BEFORE UPDATE ON public.programs
  FOR EACH ROW EXECUTE FUNCTION public.guard_breeding_business_code('code');
